// Pseudocode — citation parser + format-retry policy.
// Node: ALLaM generator output → here.
//
// Steps:
// 1. Extract [n] markers via /\[(\d+)\]/g.
// 2. If text equals canonical refusal phrase (ar OR en) → emit SubAnswer{kind:'refusal'}.
// 3. If zero [n] markers AND not refusal → retry once: "missing citations". On 2nd failure → demote to refusal.
// 4. If [n] cites n outside 1..5 → retry once: "out-of-range citation". On 2nd failure → demote to refusal.
// 5. Else → SubAnswer{kind:'answer', text, citations:[{n, chunk_id}], language}.
//
// Quiz mode: validate JSON schema instead. Same retry-then-refuse policy.
return items;

// Pseudocode — refusal builder.
// Triggered by: self-check verdict 'no' OR demoted from generator.
//
// 1. canonical_phrase ← localized per language_hint:
//      ar / mixed → 'لم أجد هذا في الكتاب المدرسي'
//      en         → "I couldn't find this in your textbook"
// 2. related_lesson_titles ← dedup top_5[0..2].metadata.lesson_title (≤ 3 unique).
// 3. Emit SubAnswer{ kind: 'refusal', canonical_phrase, related_lesson_titles, language }.
//
// No additional retrieval. Reuse already-retrieved chunks.
return items;

// Pseudocode — observability log.
//
// Sink: append-only JSONL at logs/queries.jsonl (sqlite later if we want queryable analytics during eval).
//
// One record per sub-request. Shape:
// {
//   ts, turn_id, sub_request_id,
//   session: { grade, subject, ui_locale },
//   query: { full, sub_text, language_hint },
//   decomposition: { n_sub_requests, used_llm },
//   intent: { label, raw_response },
//   retrieval: { top_20_chunk_ids, top_20_scores },
//   rerank: { top_5_chunk_ids, top_5_scores },
//   self_check: { verdict, raw },
//   generation: {
//     outcome: 'answer' | 'refusal' | 'error',
//     citation_count, citation_coverage,
//     retries, raw_first_response, final_text
//   },
//   latencies_ms: { decompose, intent, embed, retrieve, rerank, self_check, generate, total }
// }
return items;

// Pseudocode — final merge of sub-answers.
//
// 1. Concatenate sub_answers in original sub_request order.
// 2. Citation numbering is LOCAL per sub-answer block:
//    [1] in block A is unrelated to [1] in block B.
//    UI binds source cards by (sub_request_id, n).
// 3. Partial failure tolerated: a single refusal does NOT fail the whole turn.
//    Render the refusal block in place, continue rendering the rest.
//
// Output: FinalResponse { turn_id, sub_answers: SubAnswer[] }.
return items;
